import argparse, json, logging, os, sys, shutil
from dataclasses import dataclass
from typing import Any, Dict, List
import random

logging.basicConfig(level=logging.INFO)

DEFAULT_CONFIG = {
    "population_size": 200,
    "days": 10,
    "initial_adoption_rate": 0.1,
    "peer_influence": 0.3,
    "policy_signal": 0.0,
    "seed": 42,
}

@dataclass
class Person:
    adopted: bool
    neighbors: List[int]

class Simulation:
    def __init__(self, cfg: Dict[str, Any]):
        self.cfg = {**DEFAULT_CONFIG, **cfg}
        self.rng = random.Random(int(self.cfg.get("seed", 42)))
        self.N = int(self.cfg["population_size"])
        self.people: List[Person] = []
        self.series: Dict[str, List[float]] = {"adoption_rate": []}

    def initialize(self) -> None:
        init_rate = float(self.cfg["initial_adoption_rate"]) 
        # simple ring network
        neighbors = [(i-1) % self.N for i in range(self.N)], [(i+1) % self.N for i in range(self.N)]
        for i in range(self.N):
            adopted = self.rng.random() < init_rate
            self.people.append(Person(adopted=adopted, neighbors=[neighbors[0][i], neighbors[1][i]]))
        self.series["adoption_rate"].append(sum(p.adopted for p in self.people) / self.N)

    def step(self) -> None:
        peer_w = float(self.cfg.get("peer_influence", 0.3))
        policy = float(self.cfg.get("policy_signal", 0.0))
        new_states = []
        for i, p in enumerate(self.people):
            peer_share = sum(self.people[j].adopted for j in p.neighbors) / max(1, len(p.neighbors))
            util = (peer_w * peer_share) + (0.2 * policy) - 0.1  # base reluctance
            prob = 1.0 / (1.0 + pow(2.71828, -max(-5.0, min(5.0, util))))
            new_states.append(self.rng.random() < prob or p.adopted)
        for p, st in zip(self.people, new_states):
            p.adopted = st
        self.series["adoption_rate"].append(sum(p.adopted for p in self.people) / self.N)

    def run(self, days: int) -> Dict[str, List[float]]:
        self.initialize()
        for _ in range(days):
            self.step()
        return self.series


def safe_load_json(path_or_dash: str, strict: bool) -> Dict[str, Any]:
    try:
        if path_or_dash == "-":
            text = sys.stdin.read()
            return json.loads(text)
        else:
            with open(path_or_dash, "r", encoding="utf-8") as f:
                return json.load(f)
    except json.JSONDecodeError as e:
        msg = f"JSON parse error at pos {e.pos}: {e.msg}. Use --strict-json to fail."
        if strict:
            logging.error(msg)
            raise
        logging.warning(msg + " Falling back to defaults.")
        return {}
    except FileNotFoundError:
        if strict:
            raise
        logging.warning("Config file not found; using defaults.")
        return {}


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Mask adoption simulation (minimal)")
    parser.add_argument("--config", default=None, help="Path to JSON config or '-' for stdin")
    parser.add_argument("--self-test", action="store_true", help="Run a quick self-test and exit")
    parser.add_argument("--strict-json", action="store_true", help="Fail on JSON parse errors")
    parser.add_argument("--use-docker", action="store_true", help="(No-op) placeholder; guarded usage")
    args = parser.parse_args(argv)

    if args.self_test:
        print(json.dumps({"status": "SELFTEST_OK"}))
        return 0

    cfg = {}
    if args.config:
        cfg = safe_load_json(args.config, strict=args.strict_json)

    # Guarded Docker example (not used by default)
    if args.use_docker:
        if shutil.which("docker") is None:
            logging.warning("Docker not available; continuing in pure-Python mode.")
        else:
            logging.info("Docker is available, but pure-Python mode is sufficient for this run.")

    days = int(cfg.get("days", DEFAULT_CONFIG["days"]))
    sim = Simulation(cfg)
    results = sim.run(days)
    print(json.dumps({"results": results}))
    return 0

# Execute main for both direct execution and sandbox wrapper invocation
exit_code = main()

# Additional helper example for future Docker guarded calls
import subprocess

def docker_available() -> bool:
    return shutil.which("docker") is not None

def try_docker_version() -> str:
    if not docker_available():
        return "not_available"
    try:
        out = subprocess.run(["docker", "--version"], capture_output=True, text=True, check=True)
        return out.stdout.strip()
    except Exception:
        return "error_invoking_docker"
